import axios from "axios";

// Base URL for backend
const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

// ✅ 1. Fetch all deliveries
export const fetchDeliveries = () => axios.get(`${API_BASE_URL}/api/delivery`);

// ✅ 2. Assign driver to a delivery
export const assignDriver = (deliveryId: string, driverId: string) =>
  axios.put(`${API_BASE_URL}/api/delivery/${deliveryId}/assign`, { driverId });

// ✅ 3. Get delivery by ID
export const getDeliveryById = (id: string) =>
  axios.get(`${API_BASE_URL}/api/delivery/${id}`);

// ✅ 4. Create a new delivery (optional if using frontend form)
export const createDelivery = (data: {
  customerId: string;
  driverId: string;
  location: { lat: number; lng: number };
  status: string;
}) => axios.post(`${API_BASE_URL}/api/delivery`, data);
